{"path":"index.html","content":"<!doctype html>
<html lang='en'>
<head>
  <meta charset='utf-8'>
  <meta name='viewport' content='width=device-width,initial-scale=1'>
  <title>{{BUSINESS_NAME}} — Aromatherapy Experiences</title>
  <meta name='description' content='A sensory, safety-first aromatherapy session with {{PRACTITIONER_NAME}} in {{CITY}}, {{STATE}}.'>
  <link rel='stylesheet' href='assets/css/styles.css'>
  <script defer src='assets/js/main.js'></script>
</head>
<body class='aura'>
  <header class='site-header'>
    <a class='logo' href='index.html'>
      <svg width='48' height='48' viewBox='0 0 48 48' aria-hidden='true' focusable='false'>
        <defs>
          <linearGradient id='g1' x1='0' x2='1'>
            <stop offset='0' stop-color='#7BE495'/>
            <stop offset='1' stop-color='#6BCBFF'/>
          </linearGradient>
        </defs>
        <rect width='48' height='48' rx='10' fill='url(#g1)'></rect>
        <path d='M12 30c6-2 12 2 18-2' stroke='#fff' stroke-width='2' fill='none' stroke-linecap='round'></path>
      </svg>
      <div class='brand'>
        <strong>{{BUSINESS_NAME}}</strong>
        <small>{{TAGLINE}}</small>
      </div>
    </a>

    <button class='nav-toggle' aria-expanded='false' aria-controls='main-nav'>☰</button>
    <nav id='main-nav' class='nav'>
      <ul>
        <li><a href='services.html'>Offerings</a></li>
        <li><a href='blends.html'>Blends</a></li>
        <li><a href='shop.html'>Boutique</a></li>
        <li><a href='pricing.html'>Invest</a></li>
        <li><a href='about.html'>Who</a></li>
        <li><a href='book.html' class='cta'>{{PRIMARY_CTA_LABEL}}</a></li>
        <li><a href='contact.html' class='ghost'>Hello</a></li>
      </ul>
    </nav>
  </header>

  <main>
    <!-- HERO -->
    <section class='hero' style='background-image: url("assets/img/pattern.svg"), linear-gradient(135deg,#f6fff9 0%, #e7f7ff 100%);'>
      <div class='hero-inner'>
        <h1>Your private aromatherapy ritual with {{PRACTITIONER_NAME}}</h1>
        <p class='lead'>A safety-first, sensory-led experience to explore scent, calm the nervous system, and build personalized blends you can use at home. No medical claims — just thoughtful plant aromatics and experienced guidance.</p>
        <div class='hero-cta'>
          <a class='btn primary' href='{{PRIMARY_CTA_URL}}'>{{PRIMARY_CTA_LABEL}}</a>
          <a class='btn outline' href='about.html'>Meet {{PRACTITIONER_NAME}}</a>
        </div>
        <small class='note'>Sessions available in {{CITY}}, {{STATE}} — text or call {{PHONE}}</small>
      </div>
    </section>

    <!-- RITUAL -->
    <section id='ritual' class='card rhythm'>
      <div class='grid'>
        <div>
          <h2>What a ritual looks like</h2>
          <p>We begin with a short intake that prioritizes safety: sensitivities, medications, pets in the home, and pregnancy status. Then we move through scent discovery — top, middle, and base notes — followed by a gentle inhalation practice and take-home blends crafted together.</p>
          <p class='muted'>Sessions are relaxing, non-invasive, and educational. No diagnostic or therapeutic promises are made.</p>
        </div>
        <aside>
          <h3>Essentials</h3>
          <ul>
            <li>30–90 minute sessions</li>
            <li>Safe dilution guidance provided</li>
            <li>Patch test demonstration included</li>
          </ul>
        </aside>
      </div>
    </section>

    <!-- WHAT TO EXPECT -->
    <section id='expect' class='card soft'>
      <h2>What to expect</h2>
      <div class='steps'>
        <div class='step'>
          <strong>1.</strong>
          <p>Intake & safety review — we listen for allergies, medications, and pregnancy/pets concerns.</p>
        </div>
        <div class='step'>
          <strong>2.</strong>
          <p>Scent exploration — sampling of top, middle, and base notes with guided breathing.</p>
        </div>
        <div class='step'>
          <strong>3.</strong>
          <p>Blend crafting — we create a practical, labeled blend with safe dilution and usage notes.</p>
        </div>
      </div>
    </section>

    <!-- SCHEDULE -->
    <section id='schedule' class='card rhythm'>
      <h2>Schedule & availability</h2>
      <p>Pick a session length and book a time that fits. Weekday evenings and weekend mornings are common — weekday daytime slots open for those who prefer quieter hours.</p>
      <div class='schedule-grid'>
        <div class='slot'>
          <h4>30-minute Discovery</h4>
          <p class='price'>$55</p>
          <button class='btn small' data-duration='30' aria-expanded='false'>View sample times</button>
          <ul class='times' hidden>
            <li>Tue 10:00, 11:30</li>
            <li>Wed 18:00, 19:30</li>
          </ul>
        </div>
        <div class='slot'>
          <h4>60-minute Session</h4>
          <p class='price'>$120</p>
          <button class='btn small' data-duration='60' aria-expanded='false'>View sample times</button>
          <ul class='times' hidden>
            <li>Mon 14:00, 16:00</li>
            <li>Sat 09:00, 11:00</li>
          </ul>
        </div>
        <div class='slot'>
          <h4>90-minute Intensive</h4>
          <p class='price'>$185</p>
          <button class='btn small' data-duration='90' aria-expanded='false'>View sample times</button>
          <ul class='times' hidden>
            <li>Fri 17:00</li>
            <li>Sun 10:30</li>
          </ul>
        </div>
      </div>
      <p class='muted'>Times shown are examples. Booking confirms exact availability. For bespoke group events, contact {{EMAIL}}.</p>
    </section>

    <!-- PRICING (TEASER) -->
    <section id='pricing' class='card soft'>
      <h2>Investment</h2>
      <p>Pricing is transparent and scales with session length. Each session includes materials for one take-home blend and written dilution guidance.</p>
      <div class='pricing-grid'>
        <div class='price-card'>
          <h4>Discovery • 30m</h4>
          <p class='cost'>$55</p>
          <p class='meta'>Introductory scent mapping</p>
        </div>
        <div class='price-card highlight'>
          <h4>Signature • 60m</h4>
          <p class='cost'>$120</p>
          <p class='meta'>Personalized blend + education</p>
        </div>
        <div class='price-card'>
          <h4>Intensive • 90m</h4>
          <p class='cost'>$185</p>
          <p class='meta'>Extended exploration + multiple blends</p>
        </div>
      </div>
      <a class='btn primary' href='pricing.html'>See full pricing</a>
    </section>

    <!-- FAQ -->
    <section id='faq' class='card rhythm'>
      <h2>FAQ — safety-forward guidance</h2>
      <div class='faq-list'>
        <details>
          <summary>How do you dilute essential oils?</summary>
          <div class='answer'>We provide conservative dilution recommendations (usually 1–3% for adults for leave-on products). We never prescribe stronger concentrations and will adapt based on age, sensitivities, and pregnancy status. Please follow written instructions included with your blends.</div>
        </details>

        <details>
          <summary>What about patch testing?</summary>
          <div class='answer'>A patch test is recommended for leave-on blends. We'll demonstrate how to perform one using a small amount on the inner forearm and observe for 24 hours. If irritation occurs, discontinue use and consult a medical professional.</div>
        </details>

        <details>
          <summary>Are essential oils safe around pets?</summary>
          <div class='answer'>Some oils can be problematic for animals. I will review pet exposure and provide pet-safe options and diffuser practices. Always keep topical products away from pets and avoid strong diffusions in small, enclosed spaces with animals.</div>
        </details>

        <details>
          <summary>Pregnancy & aromatherapy — is it allowed?</summary>
          <div class='answer'>Pregnancy is a contraindication for some oils. We follow conservative safety protocols and will avoid or substitute oils as needed. If pregnant, please disclose during booking so we can tailor a safe session.</div>
        </details>

        <details>
          <summary>Do you make claims about treating conditions?</summary>
          <div class='answer'>No. Sessions are educational and experiential. We do not diagnose or offer medical treatment. Please consult a licensed healthcare provider for medical concerns.</div>
        </details>
      </div>
    </section>

    <!-- CTA -->
    <section class='card cta-card'>
      <div class='grid'>
        <div>
          <h2>Ready to begin?</h2>
          <p>Book an aromatic session with {{PRACTITIONER_NAME}} and leave with tools you can safely use at home.</p>
        </div>
        <div class='cta-actions'>
          <a class='btn primary large' href='{{PRIMARY_CTA_URL}}'>{{PRIMARY_CTA_LABEL}}</a>
          <a class='btn outline' href='contact.html'>Ask a quick question</a>
        </div>
      </div>
    </section>
  </main>

  <footer class='site-footer'>
    <div class='wrap'>
      <div class='foot-grid'>
        <div>
          <strong>{{BUSINESS_NAME}}</strong>
          <p class='muted'>{{TAGLINE}}</p>
        </div>
        <div>
          <p>Call or text: <a href='tel:{{PHONE}}'>{{PHONE}}</a></p>
          <p>Email: <a href='mailto:{{EMAIL}}'>{{EMAIL}}</a></p>
        </div>
        <div>
          <p>Serving: {{CITY}}, {{STATE}}</p>
          <p><a href='privacy.html'>Privacy</a> · <a href='terms.html'>Terms</a></p>
        </div>
      </div>
      <small class='muted'>Please consult healthcare professionals for medical advice. Aromatherapy sessions are educational and comfort-focused.</small>
    </div>
  </footer>
</body>
</html>"} 
