{"path":"assets/css/styles.css","content":"/* Core styles for aroma editorial aesthetic */
:root{
  --bg:#f7fffb;
  --muted:#6b7280;
  --accent1:#7BE495;
  --accent2:#6BCBFF;
  --ink:#0f172a;
  --card:#ffffff;
  --shadow: 0 6px 18px rgba(11,22,40,0.06);
  --radius:12px;
  --max:1100px;
}
*{box-sizing:border-box}
html,body{height:100%}
body{margin:0;font-family:system-ui,-apple-system,'Segoe UI',Roboto,'Helvetica Neue',Arial;color:var(--ink);background:var(--bg);-webkit-font-smoothing:antialiased}
.wrap{max-width:var(--max);margin:0 auto;padding:2rem}
.site-header{display:flex;align-items:center;justify-content:space-between;padding:1rem 2rem;background:transparent}
.logo{display:flex;align-items:center;gap:0.75rem;text-decoration:none;color:inherit}
.brand strong{display:block;font-size:1rem}
.brand small{display:block;font-size:0.75rem;color:var(--muted)}
.nav{display:flex}
.nav ul{display:flex;gap:1rem;list-style:none;padding:0;margin:0}
.nav a{text-decoration:none;padding:0.4rem 0.6rem;border-radius:999px;color:var(--ink)}
.nav a.cta{background:linear-gradient(90deg,var(--accent1),var(--accent2));color:#042;box-shadow:var(--shadow)}
.nav a.ghost{border:1px solid rgba(11,22,40,0.06);padding:0.35rem 0.6rem}
.nav-toggle{display:none}

.hero{padding:4rem 1rem;background-size:cover;background-position:center}
.hero-inner{max-width:900px;margin:0 auto;padding:2rem;background:linear-gradient(180deg,rgba(255,255,255,0.6),rgba(255,255,255,0.35));border-radius:var(--radius);box-shadow:var(--shadow);backdrop-filter: blur(6px)}
.hero h1{margin:0 0 0.5rem;font-size:2rem}
.lead{color:var(--muted);margin-bottom:1rem}
.note{display:block;margin-top:1rem;color:var(--muted)}
.btn{display:inline-block;text-decoration:none;padding:0.6rem 1rem;border-radius:8px;border:0;cursor:pointer}
.btn.primary{background:linear-gradient(90deg,var(--accent1),var(--accent2));color:#042}
.btn.outline{background:transparent;border:1px solid rgba(11,22,40,0.06)}
.btn.large{padding:0.9rem 1.2rem;font-weight:600}
.btn.small{padding:0.35rem 0.6rem;font-size:0.9rem}

.card{max-width:var(--max);margin:2rem auto;padding:1.5rem;border-radius:var(--radius);background:var(--card);box-shadow:var(--shadow)}
.soft{padding:2rem}
.rhythm{padding:2rem}
.grid{display:grid;grid-template-columns:1fr 320px;gap:1.2rem;align-items:start}
@media(max-width:820px){
  .grid{grid-template-columns:1fr}
}
.steps{display:flex;gap:1rem}
.step{background:linear-gradient(180deg,#fff,#fbfff9);padding:1rem;border-radius:10px;flex:1}
.muted{color:var(--muted)}
.schedule-grid{display:grid;grid-template-columns:repeat(3,1fr);gap:1rem;margin-top:1rem}
.slot{padding:1rem;border-radius:12px;border:1px dashed rgba(11,22,40,0.04)}
.times{margin-top:0.6rem;padding-left:1rem;color:var(--muted)}
.price{font-weight:700}
.pricing-grid{display:flex;gap:1rem;margin-top:1rem}
.price-card{flex:1;padding:1rem;border-radius:10px;background:linear-gradient(180deg,#fff,#fbfff9)}
.price-card.highlight{box-shadow:0 8px 28px rgba(11,22,40,0.08);transform:translateY(-6px)}
.cost{font-size:1.25rem;font-weight:700}
.faq-list details{margin-bottom:0.8rem}
.faq-list summary{cursor:pointer;padding:0.6rem;border-radius:8px;background:linear-gradient(180deg,#fff,#fbfff9)}
.faq-list .answer{padding:0.6rem 0.8rem;color:var(--muted)}
.cta-card{background:linear-gradient(90deg,rgba(123,228,149,0.12),rgba(107,203,255,0.08));display:block}
.cta-actions{text-align:right}
@media(max-width:820px){
  .cta-actions{text-align:left}
}
.site-footer{padding:2rem;background:#fff;border-top:1px solid rgba(11,22,40,0.03)}
.foot-grid{display:flex;gap:1rem;justify-content:space-between;align-items:center}
@media(max-width:820px){.nav{display:none}.nav-toggle{display:block}.foot-grid{flex-direction:column;align-items:start}}

/* Use SVG pattern as subtle overlay */
.aura{background-image: url('../assets/img/pattern.svg');background-repeat:repeat;background-size:220px;}
"} 
{"path":"assets/js/main.js","content":"document.addEventListener('DOMContentLoaded',function(){
  // Mobile nav toggle
  var btn=document.querySelector('.nav-toggle');
  var nav=document.getElementById('main-nav');
  if(btn){
    btn.addEventListener('click',function(){
      var expanded=this.getAttribute('aria-expanded')==='true';
      this.setAttribute('aria-expanded',!expanded);
      if(nav.style.display==='flex') nav.style.display='none'; else nav.style.display='flex';
    });
  }

  // Schedule slot expanders
  var slotButtons=document.querySelectorAll('.slot .btn.small');
  slotButtons.forEach(function(b){
    b.addEventListener('click',function(){
      var times=this.parentNode.querySelector('.times');
      var open = !(times.hidden);
      times.hidden = open;
      this.setAttribute('aria-expanded',!open);
    });
  });

  // Small accessible improvements for details fallback
  if(!('open' in document.createElement('details'))){
    var details = document.querySelectorAll('details');
    details.forEach(function(d){
      var summary = d.querySelector('summary');
      var content = d.querySelector('.answer');
      summary.style.cursor='pointer';
      summary.addEventListener('click',function(){
        var visible = content.style.display==='block';
        content.style.display = visible ? 'none' : 'block';
      });
    });
  }

  // Lightweight anchor smooth scroll
  document.querySelectorAll('a[href^="#"]').forEach(function(a){
    a.addEventListener('click',function(e){
      var id=this.getAttribute('href').slice(1);
      var el=document.getElementById(id);
      if(el){e.preventDefault();el.scrollIntoView({behavior:'smooth',block:'start'});
      }
    });
  });

});"} 
